/**
 * Parse a configuration value that is expected to represent a positive integer.
 *
 * Returns the parsed positive integer, or `null` when the value is absent, empty, not a valid
 * integer, non-positive, or one of the "disabled" sentinels (`'0'`, `'false'`, `'null'`,
 * `'undefined'`).
 */
export const parsePositiveIntegerConfigValue = (
  value: string | null | undefined
): number | null => {
  if (value == null) {
    return null;
  }

  const trimmed = value.trim();

  if (trimmed === '') {
    return null;
  }

  const parsed = Number(trimmed);

  if (!Number.isInteger(parsed) || parsed <= 0) {
    return null;
  }

  return parsed;
};

/**
 * Parse a package release timestamp into a `Date`.
 *
 * Returns a `Date` for valid ISO date strings, or `null` for non-strings, empty strings, or
 * strings that do not represent a valid date.
 */
export const parseReleaseTime = (value: unknown): Date | null => {
  if (typeof value !== 'string' || value.trim() === '') {
    return null;
  }

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return null;
  }

  return date;
};

/**
 * Parse an unknown value into a plain map of package version -> release time.
 *
 * Returns a plain object mapping string keys to string values for valid objects, or `null` for
 * non-objects (strings, arrays, `null`, `undefined`). Entries whose value is an empty string are
 * omitted from the result.
 */
export const parsePackageTimeMap = (value: unknown): Record<string, string> | null => {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    return null;
  }

  const result: Record<string, string> = {};

  for (const [key, val] of Object.entries(value)) {
    if (typeof val === 'string' && val !== '') {
      result[key] = val;
    }
  }

  return result;
};

/** Compute the age, in whole (floored) minutes, between `referenceDate` and `publishedAt`. */
export const getAgeInMinutes = (referenceDate: Date, publishedAt: Date): number => {
  return Math.floor((referenceDate.getTime() - publishedAt.getTime()) / 60_000);
};

/**
 * Given a map of version -> release time, find the latest stable (non-prerelease) version that is
 * at least `minimumAgeGateInMinutes` old relative to `referenceTime`.
 *
 * Returns the version string, or `null` when no qualifying version exists.
 */
export const getLatestStableVersionAdheringToMinimumAgeGate = (
  versionToReleaseTime: Record<string, string>,
  minimumAgeGateInMinutes: number,
  referenceTime: Date = new Date()
): string | null => {
  let latest: string | null = null;

  for (const [version, releaseTime] of Object.entries(versionToReleaseTime)) {
    if (!semver.valid(version) || semver.prerelease(version) !== null) {
      continue;
    }

    const publishedAt = parseReleaseTime(releaseTime);

    if (publishedAt === null) {
      continue;
    }

    if (getAgeInMinutes(referenceTime, publishedAt) < minimumAgeGateInMinutes) {
      continue;
    }

    if (latest === null || semver.gt(version, latest)) {
      latest = version;
    }
  }

  return latest;
};

/**
 * The core set of package name patterns that Storybook installs during `create`/`upgrade` flows.
 * If a user configures minimum-release-age exclusions, these all need to be covered for the
 * Storybook workflow to proceed without an age gate.
 */
const STORYBOOK_CORE_PACKAGE_PATTERNS = ['storybook', '@storybook/*', 'create-storybook'];

/** Convert a glob-style pattern (only `*` wildcards) into an anchored regular expression. */
const globPatternToRegExp = (pattern: string): RegExp => {
  const escaped = pattern.replace(/[.+^${}()|[\]\\]/g, '\\$&').replace(/\*/g, '.*');
  return new RegExp(`^${escaped}$`);
};

/**
 * Determine whether the configured minimum-release-age exclusion patterns cover all of the core
 * Storybook package patterns.
 *
 * Configured patterns may use glob-style `*` wildcards. Returns `true` only when every core
 * Storybook pattern is matched by at least one configured pattern.
 */
export const hasStorybookMinimumAgeExclusions = (configuredPatterns: string[]): boolean => {
  return STORYBOOK_CORE_PACKAGE_PATTERNS.every((corePattern) =>
    configuredPatterns.some((configured) => globPatternToRegExp(configured).test(corePattern))
  );
};

/** Build the human-readable instruction telling the user how to rerun the Storybook flow. */
export const getStorybookRerunInstruction = (action: 'create' | 'upgrade'): string => {
  return action === 'create'
    ? 'Please rerun Storybook creation with:'
    : 'Please rerun the Storybook upgrade with:';
};

/** Build the CLI command that reruns the Storybook flow pinned to a specific version. */
export const getStorybookRerunCommand = (action: 'create' | 'upgrade', version: string): string => {
  return action === 'create'
    ? `npx create-storybook@${version}`
    : `npx storybook@${version} upgrade`;
};

/**
 * Extract log text from an error-like object by joining its non-empty `shortMessage`, `stderr`, and
 * `message` fields (in that order) with newlines. Absent or empty fields are omitted.
 */
export const getErrorLogs = (
  error: { shortMessage?: string; stderr?: string; message?: string } | null | undefined
): string => {
  return [error?.shortMessage, error?.stderr, error?.message]
    .filter((field): field is string => typeof field === 'string' && field.length > 0)
    .join('\n');
